import {drawAncientBellGate} from './bell-scenery.js?v=0.87.0';
import {questPropSprite} from './quest-prop-art.js?v=0.87.0';
// Animated map-native artwork shares the world's tile coordinates and puzzle state.
export const MECHANISM_ART={marchMeadow:'hearth',burrowHollow:'counterweight',glassSluice:'sluice',emberQuarry:'foundry',stormBluffs:'beacon',orchardCanopy:'irrigation',reedSanctuary:'reedfilter',coralGrotto:'tidegate',moonlitDepths:'mourninglamp',relicCrags:'witnessseal',philomereBackwaters:'floodlock',smugglersWeir:'ferrylamp',saltFlats:'ledger',rescueGlade:'signalbell',anglersReach:'netwinch'};
const rect=(c,x,y,w,h,fill)=>{c.fillStyle=fill;c.fillRect(x,y,w,h);};
function stone(c,x,y,w=36,h=32){rect(c,x-2,y+3,w+4,h+3,'#182b2e88');rect(c,x,y,w,h,'#314b4e');rect(c,x+2,y+2,w-4,h-4,'#708883');rect(c,x+3,y+2,w-6,3,'#b4c0a0');rect(c,x+3,y+h-6,w-6,4,'#415b58');for(let n=0;n<3;n++)rect(c,x+4+n*10,y+9+(n%2)*10,6,1,'#415b58');rect(c,x+w-7,y+4,4,6,'#627d40');}
function wood(c,x,y,w,h){rect(c,x-1,y-1,w+2,h+2,'#34291f');rect(c,x,y,w,h,'#956d43');for(let n=0;n<h;n+=5){rect(c,x+1,y+n,w-2,1,'#cfac75');rect(c,x+3,y+n+2,w-6,1,'#6f5035');}rect(c,x+2,y+2,2,2,'#c7b894');rect(c,x+w-4,y+h-4,2,2,'#c7b894');}
function wheel(c,x,y,r,angle=0){c.save();c.translate(x,y);c.rotate(angle);c.strokeStyle='#332d25';c.lineWidth=4;c.beginPath();c.arc(0,0,r,0,Math.PI*2);c.stroke();c.strokeStyle='#c4b382';c.lineWidth=2;c.beginPath();c.arc(0,0,r,0,Math.PI*2);c.stroke();for(let n=0;n<4;n++){c.beginPath();c.moveTo(-r,0);c.lineTo(r,0);c.stroke();c.rotate(Math.PI/4);}rect(c,-2,-2,4,4,'#e6d7a2');c.restore();}
function flame(c,x,y,lit,time,reduced){if(!lit){rect(c,x-3,y-4,6,4,'#253637');return;}const w=reduced?0:Math.sin(time/170+x)*2;const g=c.createRadialGradient(x,y-8,1,x,y-8,24);g.addColorStop(0,'#ffe4a044');g.addColorStop(1,'#ffbd4a00');c.fillStyle=g;c.fillRect(x-24,y-32,48,48);c.fillStyle='#f77e39';c.beginPath();c.moveTo(x-7,y);c.quadraticCurveTo(x-11,y-9,x+w,y-22);c.quadraticCurveTo(x+11,y-8,x+7,y);c.fill();c.fillStyle='#fff2b8';c.beginPath();c.moveTo(x-3,y);c.quadraticCurveTo(x-6,y-7,x-w/2,y-15);c.quadraticCurveTo(x+6,y-6,x+3,y);c.fill();}
function flowingWater(c,x,y,w,h,time,clean=true){rect(c,x,y,w,h,clean?'#367991':'#343f37');c.strokeStyle=clean?'#abd9d7':'#84926c';c.lineWidth=1;for(let n=0;n<4;n++){const py=y+((time/70+n*7)%h);c.beginPath();c.moveTo(x+2,py);c.quadraticCurveTo(x+w/2,py+2,x+w-2,py);c.stroke();}}
const boulderMotion=new Map();
export function drawBoulder(c,x,y,index=0,reduced=false){const now=globalThis.performance?.now?.()||0;let pose=boulderMotion.get(index);if(!pose){pose={x,y,fromX:x,fromY:y,start:now};boulderMotion.set(index,pose);}if(pose.x!==x||pose.y!==y){const t=Math.min(1,(now-pose.start)/180);pose.fromX=pose.fromX+(pose.x-pose.fromX)*t;pose.fromY=pose.fromY+(pose.y-pose.fromY)*t;pose.x=x;pose.y=y;pose.start=now;}const t=reduced?1:Math.min(1,(now-pose.start)/180);x=pose.fromX+(pose.x-pose.fromX)*t;y=pose.fromY+(pose.y-pose.fromY)*t;const sprite=questPropSprite('boulder');if(sprite?.ready){c.save();c.translate(x*16+8,y*16+8);c.drawImage(sprite.image,-sprite.drawWidth/2,10-sprite.drawHeight,sprite.drawWidth,sprite.drawHeight);c.fillStyle='#f4e6b3';c.font='bold 8px serif';c.textAlign='center';c.fillText(String(index+1),0,0);c.restore();return;}c.save();c.translate(x*16,y*16);c.fillStyle='#25303488';c.beginPath();c.ellipse(8,13,15,6,0,0,Math.PI*2);c.fill();c.fillStyle='#6b7975';c.strokeStyle='#303f40';c.lineWidth=2;c.beginPath();c.moveTo(-6,8);c.lineTo(-3,-9);c.lineTo(8,-17);c.lineTo(23,-8);c.lineTo(25,9);c.lineTo(15,15);c.lineTo(0,14);c.closePath();c.fill();c.stroke();c.fillStyle='#a5b0a0';c.beginPath();c.moveTo(-2,-8);c.lineTo(8,-14);c.lineTo(20,-7);c.lineTo(8,0);c.fill();c.strokeStyle='#485d58';c.beginPath();c.moveTo(8,0);c.lineTo(15,11);c.lineTo(23,8);c.stroke();rect(c,0,8,5,3,'#79924a');c.fillStyle='#efdfae';c.font='bold 8px serif';c.textAlign='center';c.fillText(String(index+1),8,7);c.restore();}
export function drawQuestMechanism(c,kind,x,y,{index=0,value=0,lit=false,solved=false,time=0,reduced=false}={}){
 const sprite=questPropSprite(kind);if(sprite?.ready){c.save();c.translate(x*16+8,y*16+8);const w=sprite.drawWidth,h=sprite.drawHeight,top=10-h;c.drawImage(sprite.image,-w/2,top,w,h);if(sprite.lightAnchor&&lit){const [lx,ly]=sprite.lightAnchor;flame(c,-w/2+lx*w,top+ly*h,true,time,reduced);}if(['sluice','tidegate','floodlock','irrigation','reedfilter'].includes(kind)){c.strokeStyle=solved?'#bef2e2bb':'#c1dedc66';c.lineWidth=1;for(let n=0;n<3;n++){const py=6-n*3+(reduced?0:Math.sin(time/450+n));c.beginPath();c.moveTo(-w*.22,py);c.quadraticCurveTo(0,py+2,w*.22,py);c.stroke();}if(kind==='reedfilter'&&!solved){c.fillStyle='#353f3455';c.fillRect(-w*.3,0,w*.6,8);}}if(solved){c.strokeStyle='#cee7a899';c.lineWidth=1;c.beginPath();c.ellipse(0,10,w*.45,5,0,0,Math.PI*2);c.stroke();}c.fillStyle=solved?'#d8efad':'#fff1be';c.font='bold 8px serif';c.textAlign='center';c.fillText(kind==='counterweight'?String(value):String(index+1),0,21);c.restore();return;}
 c.save();c.translate(x*16+8,y*16+8);const t=reduced?0:time;
 if(['hearth','beacon','mourninglamp','ferrylamp'].includes(kind)){
  stone(c,-13,-12,26,21);stone(c,-8,-38,16,29);rect(c,-11,-43,22,6,'#c2b68a');rect(c,-9,-48,18,6,'#40564c');
  if(kind==='hearth'){stone(c,-19,-32,38,28);rect(c,-12,-26,24,19,'#243233');wood(c,-8,-10,16,4);}
  if(kind==='ferrylamp'){wood(c,-16,-37,5,36);rect(c,-16,-39,32,4,'#8f714b');rect(c,7,-35,13,21,'#263c43');rect(c,9,-33,9,16,lit?'#ffde88':'#617578');}
  flame(c,kind==='ferrylamp'?13:0,kind==='hearth'?-12:-47,lit,t,reduced);
 }else if(['sluice','tidegate','floodlock','irrigation'].includes(kind)){
  stone(c,-24,-29,14,39);stone(c,10,-29,14,39);flowingWater(c,-10,-24,20,35,t,true);rect(c,-11,-30,22,4,'#c9c1a0');
  const opened=solved?20:0;wood(c,-9,-23-opened,18,25);rect(c,-9,-23-opened,18,3,'#b5ae84');wheel(c,0,-36,8,solved?1.3:index*.6);
  if(kind==='irrigation'){stone(c,-24,6,48,12);flowingWater(c,-21,8,42,7,t,true);}
 }else if(kind==='reedfilter'){
  stone(c,-25,-14,50,26);flowingWater(c,-22,-12,44,20,t,solved);wood(c,-21,-19,42,4);wood(c,-21,3,42,4);
  for(let n=0;n<8;n++){const px=-18+n*5,bend=reduced?0:Math.sin(t/800+n)*1.5;c.strokeStyle=solved?'#91b658':'#788b45';c.lineWidth=2;c.beginPath();c.moveTo(px,3);c.quadraticCurveTo(px+3,-13,px+bend,-29-(n%3)*4);c.stroke();rect(c,px+bend-1,-30-(n%3)*4,3,7,'#b38b4d');}
  wheel(c,19,-19,6,solved?1:index);
 }else if(['counterweight','netwinch','foundry'].includes(kind)){
  wood(c,-20,-25,6,37);wood(c,14,-25,6,37);wood(c,-21,-30,42,7);wheel(c,0,-17,11,(kind==='counterweight'?value:index)*.8);
  c.strokeStyle='#cfc3a0';c.lineWidth=2;c.beginPath();c.moveTo(-11,-24);c.lineTo(-11,3);c.moveTo(11,-24);c.lineTo(11,3-value*3);c.stroke();
  if(kind==='counterweight'){stone(c,-18,0,14,10);stone(c,4,-value*3,14,10);for(let n=0;n<value;n++)rect(c,6,-value*3-n*4,10,3,'#c6baa0');}
  if(kind==='netwinch'){c.strokeStyle=solved?'#cfccb2':'#82928d';c.lineWidth=1;for(let n=0;n<6;n++){c.beginPath();c.moveTo(-16+n*6,0);c.lineTo(-12+n*4,14-(solved?10:0));c.moveTo(-16,n*3);c.lineTo(16,n*3);c.stroke();}}
  if(kind==='foundry'){stone(c,-17,-8,34,22);rect(c,-10,-5,20,12,'#2c3534');flame(c,0,6,true,t,reduced);rect(c,19,-13,8,5,'#688282');rect(c,23,-20,4,12,'#afbab0');}
 }else if(kind==='signalbell'){
  wood(c,-18,-36,5,45);wood(c,13,-36,5,45);wood(c,-18,-38,36,5);c.fillStyle='#bda966';c.strokeStyle='#514c35';c.lineWidth=2;c.beginPath();c.moveTo(-6,-31);c.quadraticCurveTo(-11,-29,-11,-15);c.lineTo(-15,-10);c.lineTo(15,-10);c.lineTo(11,-15);c.quadraticCurveTo(11,-29,6,-31);c.closePath();c.fill();c.stroke();rect(c,-3,-11,6,7,'#e5d099');
 }else if(kind==='witnessseal'){
  stone(c,-19,-31,38,41);rect(c,-14,-26,28,24,solved?'#839e69':'#485b59');c.strokeStyle='#e5d5a1';c.lineWidth=2;c.beginPath();c.arc(0,-14,8,0,Math.PI*2);c.moveTo(-7,-14);c.lineTo(7,-14);c.moveTo(0,-22);c.lineTo(0,-6);c.stroke();
 }else if(kind==='ledger'){
  wood(c,-23,-8,46,16);rect(c,-16,-26,32,20,'#eadbb5');rect(c,-17,-26,2,20,'#b69c6a');rect(c,0,-25,1,18,'#bda77d');for(let n=0;n<4;n++){rect(c,-12,-22+n*4,9,1,'#62716a');rect(c,4,-22+n*4,10,1,'#62716a');}wheel(c,18,-14,6,index);
 }
 c.fillStyle=solved?'#ddf2b0':'#fff0bf';c.font='bold 8px serif';c.textAlign='center';c.fillText(kind==='counterweight'?String(value):String(index+1),0,22);c.restore();
}
const gateStates=new Map();
export function drawExpeditionGate(c,room,open,time,reduced){let q=gateStates.get(room);if(!q){q={};gateStates.set(room,q);}c.save();c.translate(0,9*16);drawAncientBellGate(c,q,room,open,time,reduced);c.restore();}

export function drawEvidence(c,key,stage,x,y,collected){const kind=key==='marchMeadow'?'hearth':key==='anglersReach'?'netwinch':['moonlitDepths','relicCrags','rescueGlade'].includes(key)?'witnessseal':'ledger',sprite=questPropSprite(kind);if(sprite?.ready){c.save();c.translate(x*16+8,y*16+8);const w=sprite.drawWidth*.8,h=sprite.drawHeight*.8;c.drawImage(sprite.image,-w/2,8-h,w,h);if(collected){c.strokeStyle='#cfe7a8';c.lineWidth=1;c.beginPath();c.arc(0,11,4,0,Math.PI*2);c.stroke();}c.restore();return;}c.save();c.translate(x*16+8,y*16+8);wood(c,-12,-3,24,9);if(key==='marchMeadow'){wood(c,-13,-15,26,13);c.strokeStyle='#d5bc87';c.beginPath();c.arc(0,-13,11,Math.PI,0);c.stroke();rect(c,-8,-11,16,6,collected?'#849378':'#f0e7c9');}else if(key==='anglersReach'){c.strokeStyle='#c1c9b2';for(let n=0;n<5;n++){c.beginPath();c.moveTo(-13+n*6,-21);c.lineTo(-12+n*6,0);c.moveTo(-13,-20+n*5);c.lineTo(12,-20+n*5);c.stroke();}}else if(['moonlitDepths','relicCrags','rescueGlade'].includes(key)){stone(c,-14,-28,28,28);rect(c,-9,-23,18,1,'#d8d7b4');rect(c,-9,-18,16,1,'#d8d7b4');rect(c,-9,-13,13,1,'#d8d7b4');}else{rect(c,-12,-23,24,20,'#e7d6aa');rect(c,-13,-23,3,20,'#b09a72');for(let n=0;n<4;n++)rect(c,-8,-19+n*4,15,1,'#5b7066');rect(c,5,-8,4,4,collected?'#72965b':'#b07450');}c.restore();}
